import type { KataTest } from "../katas/types.ts";

export type SandboxRequest = {
  // Untrusted code generated by a model.
  code: string;
  functionName: string;
  tests: readonly KataTest[];
};

export type SandboxOutcome = { label: string; status: "passed" | "failed" | "timeout" };

export type SandboxReport = {
  status: "completed" | "load-error" | "timeout";
  outcomes: SandboxOutcome[];
  loadError?: string;
};

// Messages relayed from the worker, through the sandbox iframe, to the page.
export type SandboxMessage =
  | { type: "result"; outcome: { label: string; status: "passed" | "failed" } }
  | { type: "load-error"; message: string }
  | { type: "done" };
